action.code:
if (open_list.empty()) {
    return nullptr;
}
auto next_node = *std::min_element(open_list.begin(), open_list.end(),
    [](const RouteModel::Node* a, const RouteModel::Node* b) {
        return a->g_value + a->h_value < b->g_value + b->h_value;
    });
open_list.erase(std::remove(open_list.begin(), open_list.end(), next_node), open_list.end());
return next_node;

